// Review R1: the JS terrain-v2 score (scripts/lib/fsi-score.mjs) must equal the Python reference
// (fsi/pipeline/config_v2.py), which test_sql_018.py already pins to SQL fsi_static_v2_expr.
// Expected numbers come from tests/map/fixtures/fsi-v2-python.json, generated by gen-fsi-v2.py.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as score from '../../scripts/lib/fsi-score.mjs';

const fx = JSON.parse(readFileSync(new URL('./fixtures/fsi-v2-python.json', import.meta.url), 'utf8'));

test('v2 weights equal config_v2.W2 and sum to 1', () => {
  assert.deepEqual({ ...score.W2 }, fx.weights);
  const sum = Object.values(score.W2).reduce((a, b) => a + b, 0);
  assert.ok(Math.abs(sum - 1) < 1e-12);
});

test(`staticScoreV2 equals Python static_score_v2 on ${fx.cases.length} cases`, () => {
  let worst = 0;
  for (const c of fx.cases) {
    const js = score.staticScoreV2(c.in);
    const d = Math.abs(js - c.static_v2);
    worst = Math.max(worst, d);
    assert.ok(d <= 1e-9, `static_v2 ${JSON.stringify(c.in)}: js ${js} python ${c.static_v2}`);
  }
  assert.ok(worst <= 1e-9);
});

test('term helpers equal the Python terms', () => {
  for (const c of fx.cases) {
    const i = c.in;
    const near = (a, b, what) => assert.ok((a == null && b == null) || Math.abs(a - b) <= 1e-12, `${what} ${JSON.stringify(i)}: ${a} vs ${b}`);
    near(score.bowlScore(i.nbr_rel_m, i.street_rel_m), c.terms.bowl, 'bowl');
    near(score.soilScoreV2(i.hsg_eff, i.drain_class, i.ksat_um_s), c.terms.soil, 'soil');
    near(score.wtScore(i.wt_depth_m), c.terms.wt, 'wt');
    near(score.ksatScore(i.ksat_um_s), c.terms.ksat, 'ksat');
  }
});

test('staticScoreForRow: v2 only when the row says so and has a v2 score; v1 unchanged otherwise', () => {
  const row = { twi_n: 0.8, hand_n: 0.3, depr_n: 0.4, hsg: 'C', fema_zone: 'X', fsi_static_v2: 0.61 };
  const v1 = score.staticScore(0.8, 0.3, 'C', 'X', 0.4);
  assert.equal(score.staticScoreForRow(row), v1);
  assert.equal(score.staticScoreForRow({ ...row, model_version: 'v1' }), v1);
  assert.equal(score.staticScoreForRow({ ...row, model_version: 'v2' }), 0.61);
  assert.equal(score.staticScoreForRow({ ...row, model_version: 'v2', fsi_static_v2: null }), v1);
  assert.equal(score.staticScoreForRow({ hsg: 'D', fema_zone: 'AE' }), score.staticScoreLite('D', 'AE'));
});

test('v1 weights are untouched', () => {
  assert.deepEqual([score.W_TWI, score.W_HAND, score.W_DEPR, score.W_SOIL, score.W_ZONE], [0.3, 0.2, 0.2, 0.15, 0.15]);
});
